```tsx
// src/CheckoutPage.tsx

import React, { useMemo, useState } from "react";
import { CartItem, DeliveryAddress, AddressErrors } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  cartItems: CartItem[];
  shippingCost?: number;
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
  isSubmitting?: boolean;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(amount: number): string {
  return amount.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required.";
  }
  if (!address.street.trim()) {
    errors.street = "Street address is required.";
  }
  if (!address.city.trim()) {
    errors.city = "City is required.";
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) {
    errors.country = "Country is required.";
  }
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  cartItems,
  shippingCost = 4.99,
  onBackToCart,
  onPay,
  isSubmitting = false,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [cartItems]
  );
  const total = subtotal + (cartItems.length > 0 ? shippingCost : 0);

  function handleChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  function handleBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress({ ...address }));
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length === 0) {
      onPay(address);
    }
  }

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-label="Order summary">
          <h2>Your order</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="cart-totals">
            <div className="cart-totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="cart-totals-row">
              <span>Shipping</span>
              <span>
                {cartItems.length > 0 ? formatPrice(shippingCost) : formatPrice(0)}
              </span>
            </div>
            <div className="cart-totals-row cart-totals-total">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="address-section" aria-label="Delivery address">
          <h2>Delivery address</h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <label className="form-field">
              <span>Full name</span>
              <input
                type="text"
                value={address.fullName}
                onChange={(e) => handleChange("fullName", e.target.value)}
                onBlur={() => handleBlur("fullName")}
                aria-invalid={Boolean(fieldError("fullName"))}
              />
              {fieldError("fullName") && (
                <span className="field-error">{fieldError("fullName")}</span>
              )}
            </label>

            <label className="form-field">
              <span>Street address</span>
              <input
                type="text"
                value={address.street}
                onChange={(e) => handleChange("street", e.target.value)}
                onBlur={() => handleBlur("street")}
                aria-invalid={Boolean(fieldError("street"))}
              />
              {fieldError("street") && (
                <span className="field-error">{fieldError("street")}</span>
              )}
            </label>

            <div className="form-row">
              <label className="form-field">
                <span>City</span>
                <input
                  type="text"
                  value={address.city}
                  onChange={(e) => handleChange("city", e.target.value)}
                  onBlur={() => handleBlur("city")}
                  aria-invalid={Boolean(fieldError("city"))}
                />
                {fieldError("city") && (
                  <span className="field-error">{fieldError("city")}</span>
                )}
              </label>

              <label className="form-field">
                <span>Postal code</span>
                <input
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleChange("postalCode", e.target.value)}
                  onBlur={() => handleBlur("postalCode")}
                  aria-invalid={Boolean(fieldError("postalCode"))}
                />
                {fieldError("postalCode") && (
                  <span className="field-error">{fieldError("postalCode")}</span>
                )}
              </label>
            </div>

            <label className="form-field">
              <span>Country</span>
              <input
                type="text"
                value={address.country}
                onChange={(e) => handleChange("country", e.target.value)}
                onBlur={() => handleBlur("country")}
                aria-invalid={Boolean(fieldError("country"))}
              />
              {fieldError("country") && (
                <span className="field-error">{fieldError("country")}</span>
              )}
            </label>

            <label className="form-field">
              <span>Phone number</span>
              <input
                type="tel"
                value={address.phone}
                onChange={(e) => handleChange("phone", e.target.value)}
                onBlur={() => handleBlur("phone")}
                aria-invalid={Boolean(fieldError("phone"))}
              />
              {fieldError("phone") && (
                <span className="field-error">{fieldError("phone")}</span>
              )}
            </label>

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onBackToCart}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={cartItems.length === 0 || isSubmitting}
              >
                {isSubmitting ? "Processing..." : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

