// src/App.tsx (usage example)

import React, { useState } from "react";
import CheckoutPage from "./CheckoutPage";
import { CartItem, DeliveryAddress } from "./types";

const mockCartItems: CartItem[] = [
  {
    id: "1",
    name: "Wireless Headphones",
    imageUrl: "https://via.placeholder.com/56",
    unitPrice: 79.99,
    quantity: 1,
  },
  {
    id: "2",
    name: "USB-C Charging Cable",
    imageUrl: "https://via.placeholder.com/56",
    unitPrice: 12.5,
    quantity: 2,
  },
];

export default function App() {
  const [isSubmitting, setIsSubmitting] = useState(false);

  function handleBackToCart() {
    console.log("Navigate back to /cart");
  }

  function handlePay(address: DeliveryAddress) {
    setIsSubmitting(true);
    console.log("Submitting payment with address:", address);
    setTimeout(() => setIsSubmitting(false), 1500);
  }

  return (
    <CheckoutPage
      cartItems={mockCartItems}
      onBackToCart={handleBackToCart}
      onPay={handlePay}
      isSubmitting={isSubmitting}
    />
  );
}
```

Notes on behavior:
- `onBackToCart` and `onPay` are passed in by the parent so you can wire them to your router/payment logic — `onPay` receives the validated `DeliveryAddress`.
- Form validation runs on blur per-field and fully on submit; the Pay button is disabled while `isSubmitting` is true or the cart is empty.
- Layout is a responsive two-column grid (summary + form) that collapses to one column under 720px.
